"""Guard/Baileys operations admin dashboard shell."""

ADMIN_DASHBOARD_PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Guard Operations</title>
<style>
:root{font-family:Inter,system-ui,sans-serif;color:#17202a;background:#f3f6f8;line-height:1.4}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1180px;margin:auto;padding:28px 18px 60px}h1,h2,p{margin:0}.muted{color:#6d7b86;font-size:.86rem}.top{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:20px}.badge{display:inline-flex;align-items:center;padding:6px 11px;border-radius:999px;background:#e4f6ec;color:#176b43;font-size:.78rem;font-weight:700}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:18px}.card,.panel{background:#fff;border:1px solid #dbe3e8;border-radius:14px;box-shadow:0 2px 8px #1b34400b}.card{padding:16px}.card strong{display:block;font-size:1.8rem}.card span{font-size:.8rem;color:#6d7b86}.panel{padding:18px;margin-top:18px}.panel h2{font-size:1.05rem;margin-bottom:12px}.toolbar{display:flex;justify-content:flex-end;margin-bottom:10px}.toolbar button{border:1px solid #cbd5dc;border-radius:8px;background:#fff;padding:8px 12px;cursor:pointer}.table{width:100%;border-collapse:collapse;font-size:.86rem}.table th,.table td{text-align:left;padding:10px 8px;border-bottom:1px solid #edf0f2;vertical-align:top}.state{font-weight:700}.connected{color:#16834d}.degraded,.pairing_required,.unavailable{color:#b45b00}.error{color:#c23b3b}.chart{height:190px;display:flex;align-items:end;gap:8px;padding:12px 4px;border-bottom:1px solid #dbe3e8}.bar{min-width:18px;background:#2a78d0;border-radius:5px 5px 0 0;position:relative}.bar span{position:absolute;bottom:-24px;left:50%;transform:translateX(-50%);font-size:10px;color:#6d7b86;white-space:nowrap}.empty{padding:18px 0}.mono{font-family:ui-monospace,monospace;font-size:.76rem;word-break:break-all}@media(max-width:800px){.grid{grid-template-columns:repeat(2,1fr)}.table{display:block;overflow-x:auto;white-space:nowrap}}
</style></head><body><main class="wrap">
<header class="top"><div><h1>Guard Operations</h1><p class="muted">Live Baileys connection health and connection-state history</p></div><span class="badge">Admin</span></header>
<section id="cards" class="grid"></section>
<section class="panel"><div class="toolbar"><button onclick="load()">Refresh</button></div><h2>Connection health</h2><div id="connections" class="empty muted">Loading…</div></section>
<section class="panel"><h2>State history</h2><div id="chart" class="chart"></div></section>
<section class="panel"><h2>Recent Security and Exposure alerts</h2><div id="alerts" class="empty muted">Loading…</div></section>
<section class="panel"><h2>Recent processing errors</h2><div id="errors" class="empty muted">Loading…</div></section>
</main><script>
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v?new Date(v).toLocaleString():'—';
async function load(){try{const r=await fetch('/api/debug/guard/admin');if(!r.ok)throw Error('Admin access denied');const d=await r.json();render(d)}catch(e){document.body.innerHTML='<main class="wrap"><h1>Unable to load dashboard</h1><p class="muted">'+esc(e.message)+'</p></main>'}}
function render(d){const c=d.counts;document.getElementById('cards').innerHTML=[['connected','Connected now'],['pairing_required','Pairing required'],['degraded','Degraded/unavailable'],['total','Total connections']].map(([k,l])=>'<div class="card"><strong>'+esc(c[k])+'</strong><span>'+l+'</span></div>').join('');
document.getElementById('connections').innerHTML='<table class="table"><thead><tr><th>Child</th><th>Connection</th><th>Persisted</th><th>Live status</th><th>Raw status</th><th>Checked</th><th>Updated</th></tr></thead><tbody>'+d.connections.map(x=>'<tr><td><strong>'+esc(x.child_name)+'</strong><br><span class="muted mono">'+esc(x.user_id)+'</span></td><td class="mono">'+esc(x.connection_id)+'</td><td>'+esc(x.persisted_status)+'<br><span class="muted">'+esc(x.persisted_raw_status)+'</span></td><td class="state '+esc(x.live.status)+'">'+esc(x.live.status)+'</td><td>'+esc(x.live.provider_raw_status)+'</td><td>'+esc(fmt(x.live.checked_at))+'</td><td>'+esc(fmt(x.updated_at))+'</td></tr>').join('')+'</tbody></table>';
const alerts=d.alerts||[];document.getElementById('alerts').innerHTML=alerts.length?'<table class="table"><thead><tr><th>Type</th><th>Child</th><th>Chat</th><th>Decision</th><th>Category</th><th>Created</th></tr></thead><tbody>'+alerts.map(a=>'<tr><td>'+esc(a.kind)+'</td><td>'+esc(a.child_name)+'</td><td>'+esc(a.chat_name)+'</td><td>'+esc(a.decision)+'</td><td>'+esc(a.category)+'</td><td>'+esc(fmt(a.created_at))+'</td></tr>').join('')+'</tbody></table>':'No recent Security or Exposure assessments.';
const groups={};for(const e of d.events){const n=e.payload?.status||'unknown';groups[n]=(groups[n]||0)+1}const max=Math.max(1,...Object.values(groups));document.getElementById('chart').innerHTML=Object.entries(groups).map(([k,v])=>'<div class="bar" style="height:'+Math.max(8,Math.round(v/max*150))+'px"><span>'+esc(k)+' ('+v+')</span></div>').join('')||'<div class="empty muted">No state events</div>';
document.getElementById('errors').innerHTML=d.errors.length?'<table class="table"><thead><tr><th>Event</th><th>Attempts</th><th>Error</th><th>Updated</th></tr></thead><tbody>'+d.errors.map(x=>'<tr><td class="mono">'+esc(x.event_id)+'</td><td>'+esc(x.attempt_count)+'</td><td class="error">'+esc(x.last_error)+'</td><td>'+esc(fmt(x.updated_at))+'</td></tr>').join('')+'</tbody></table>':'No recent processing errors.'}
load();setInterval(load,30000);
</script></body></html>'''
